Algorithm SinValor
  Define premio As Integer;
  Define puntos As Integer <- 40;
  If puntos > 50 Then
    premio <- 10;
  EndIf
  Write premio;
EndAlgorithm

Algorithm ConValor
  Define premio As Integer;
  Define puntos As Integer <- 40;
  If puntos > 50 Then
    premio <- 10;
  Else
    premio <- 0;
  EndIf
  Write premio;
EndAlgorithm

Algorithm Bucle
  Define ultimo As Integer;
  Define i As Integer <- 0;
  While i < 3 Do
    ultimo <- i;
    i <- i + 1;
  EndWhile
  Write ultimo;
EndAlgorithm
